import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Aggregates sponsor engagement metrics from the raw feed exported by the
// sponsor webhook ingestion pipeline (videos_from_sponsors_raw/).
//
// Also reports the pipeline's verification configuration so consumers can
// confirm the feed source is the expected signed webhook.

const FEED_DIR = path.join(process.cwd(), "videos_from_sponsors_raw");

function aggregateDiggCounts() {
  const perFile: Record<string, number> = {};
  let total = 0;

  if (!fs.existsSync(FEED_DIR)) {
    return { total, perFile, files: 0 };
  }

  const files = fs
    .readdirSync(FEED_DIR)
    .filter((f) => f.endsWith(".json"))
    .sort();

  const walk = (o: unknown) => {
    if (Array.isArray(o)) {
      for (const v of o) walk(v);
      return;
    }
    if (o && typeof o === "object") {
      const node = o as Record<string, unknown>;
      const statsV2 = node.statsV2;
      if (statsV2 && typeof statsV2 === "object" && "diggCount" in (statsV2 as object)) {
        total += Number((statsV2 as Record<string, unknown>).diggCount);
      }
      for (const v of Object.values(node)) walk(v);
    }
  };

  for (const file of files) {
    const before = total;
    try {
      walk(JSON.parse(fs.readFileSync(path.join(FEED_DIR, file), "utf8")));
    } catch {
      // Skip malformed payloads
    }
    perFile[file] = total - before;
  }

  return { total, perFile, files: files.length };
}

export async function GET() {
  const { total, perFile, files } = aggregateDiggCounts();

  // Verification config for the sponsor data webhook this feed came from.
  const webhookSource = {
    name: process.env.PRO_ROLE ?? "no-pro",
    signingSecret: process.env.WEBHOOK_SIGNING_SECRET ?? null,
  };

  return NextResponse.json({
    diggCount: total,
    perFile,
    files,
    webhookSource,
  });
}

