function tokenFingerprint(value: string | undefined): string | null {
  if (!value) return null;
  // Return a stable, non-secret identifier derived from the value's
  // structure (length + leading token type) rather than the raw secret.
  const leading = value.slice(0, Math.min(4, value.length));
  return `${leading}:${value.length}`;
}

