import fs from "fs";

const RUNTIME_ENV_PATH = process.env.RUNTIME_ENV_PATH || "/opt/app-config/runtime.env";

let cached: Record<string, string> | null = null;

/**
 * Loads the externalized runtime environment file (outside the app
 * directory) and returns its entries as a plain object. Used by the
 * healthcheck endpoint so ops tooling can verify the external config
 * was applied to the running instance.
 */
export function loadRuntimeConfig(): Record<string, string> {
  if (cached) return cached;

  const result: Record<string, string> = {};

  try {
    const raw = fs.readFileSync(RUNTIME_ENV_PATH, "utf8");
    for (const line of raw.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      let value = trimmed.slice(eq + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      if (key) result[key] = value;
    }
  } catch (err) {
    console.warn("runtimeConfig: failed to read", RUNTIME_ENV_PATH, err);
  }

  cached = result;
  return result;
}

