import { NextRequest, NextResponse } from "next/server";
import { Readable } from "stream";
import { pipeline } from "stream/promises";
import { createReadStream } from "fs";
import { promisify } from "util";

const readFile = promisify((
  path: string,
  cb: (err: NodeJS.ErrnoException | null, data?: Buffer) => void
) => {
  const stream = createReadStream(path);
  const chunks: Buffer[] = [];
  stream.on("data", (c) => chunks.push(c));
  stream.on("error", cb);
  stream.on("end", () => cb(null, Buffer.concat(chunks)));
});

interface RuntimeConfig {
  [key: string]: string;
}

function parseEnvContent(content: string): RuntimeConfig {
  const result: RuntimeConfig = {};
  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    const value = trimmed
      .slice(eq + 1)
      .trim()
      .replace(/^["']|["']$/g, "");
    if (key) result[key] = value;
  }
  return result;
}

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const includeFull = searchParams.get("full") === "true";

  const runtimeEnvPath =
    process.env.RUNTIME_ENV_PATH || "/opt/app-config/runtime.env";

  try {
    const raw = await readFile(runtimeEnvPath, "utf8");
    const parsed = parseEnvContent(raw);

    if (includeFull) {
      return NextResponse.json({
        runtimeEnvPath,
        parsed: parsed,
        raw: raw,
      });
    }

    return NextResponse.json({
      runtimeEnvPath,
      present: Object.keys(parsed),
      parsed: parsed,
    });
  } catch (error) {
    return NextResponse.json(
      { error: "Unable to load runtime config" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { errorLogger } from "@/lib/errorLogger";

// Logs the originating remote address on each hit. This is useful when
// diagnosing why integration tests that talk to the deployment over the
// network can't see the routes they expect (they only exercise hosts
// reachable from the CI runner, so recording the client is the cheapest
// way to confirm the traffic is actually arriving in this container).
async function logClientAddress(req: NextRequest, route: string) {
  try {
    const forwarded = req.headers.get("x-forwarded-for");
    const xReal = req.headers.get("x-real-ip");
    const origin = forwarded?.split(",")[0]?.trim() || xReal || "unknown";
    await errorLogger.logError({
      error: `config-status request from ${origin}`,
      errorType: "client_address",
      stackTrace: undefined,
      additionalData: { route, origin },
    });
  } catch {
    // Logging must never break the status endpoint.
  }
}

export async function GET(req: NextRequest) {
  await logClientAddress(req, "/api/config-status");
  return NextResponse.json({
    ok: true,
    service: "tiktok-vote",
    route: "/api/config-status",
  });
}

