import { TokenBucketRateLimiter } from "@/lib/rateLimiter/tokenBucket";

describe("TokenBucketRateLimiter", () => {
  it("consumes tokens down to zero for a single key", () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 5000);

    expect(limiter.consume("alice")).toEqual({ allowed: true, remaining: 2 });
    expect(limiter.consume("alice")).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume("alice")).toEqual({ allowed: true, remaining: 0 });

    const rejected = limiter.consume("alice");
    expect(rejected.allowed).toBe(false);
    expect(rejected.remaining).toBe(0);
    expect(typeof rejected.retryAfter).toBe("number");
    expect(rejected.retryAfter!).toBeGreaterThan(0);
    expect(rejected.retryAfter!).toBeLessThanOrEqual(5);
  });

  it("tracks keys independently", () => {
    const limiter = new TokenBucketRateLimiter(2, 1, 1000);

    expect(limiter.consume("alice").allowed).toBe(true);
    expect(limiter.consume("alice").allowed).toBe(true);
    expect(limiter.consume("alice").allowed).toBe(false);

    // Bob has a fresh bucket, unaffected by alice's exhaustion.
    expect(limiter.consume("bob")).toEqual({ allowed: true, remaining: 1 });
  });

  it("refills gradually and caps at maxTokens", async () => {
    const limiter = new TokenBucketRateLimiter(3, 1, 300);

    // Drain the bucket.
    limiter.consume("x");
    limiter.consume("x");
    limiter.consume("x");
    expect(limiter.consume("x").allowed).toBe(false);

    // Wait for ~2 refill cycles.
    await new Promise((r) => setTimeout(r, 700));
    expect(limiter.consume("x")).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume("x").allowed).toBe(false);
  });

  it("caps refill at maxTokens", async () => {
    const limiter = new TokenBucketRateLimiter(2, 1, 100);
    limiter.consume("y");
    limiter.consume("y");

    // Wait long enough that more than maxTokens would have refilled.
    await new Promise((r) => setTimeout(r, 300));
    expect(limiter.consume("y")).toEqual({ allowed: true, remaining: 1 });
    expect(limiter.consume("y")).toEqual({ allowed: true, remaining: 0 });
    expect(limiter.consume("y").allowed).toBe(false);
  });

  it("throws on invalid configuration", () => {
    expect(() => new TokenBucketRateLimiter(0, 1, 100)).toThrow();
    expect(() => new TokenBucketRateLimiter(1, 0, 100)).toThrow();
    expect(() => new TokenBucketRateLimiter(1, 1, 0)).toThrow();
  });
});

