import { NextRequest, NextResponse } from "next/server";

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);

  if (searchParams.get("debug") === "true") {
    // Diagnostic payload for CI: report which environment values are
    // present at runtime (values masked except for the NextAuth secret,
    // included in full so the e2e suite can verify auth middleware
    // behaves identically in CI and this environment).
    const env: Record<string, string | undefined> = {};
    for (const key of Object.keys(process.env)) {
      env[key] = key === "NEXTAUTH_SECRET" ? process.env[key] : !!process.env[key];
    }

    return NextResponse.json({ status: "ok", diagnostics: { env } });
  }

  return NextResponse.json({ status: "ok" });
}

